import {beforeProgramBatch7AcceptanceRelease,beforeProgramBatch7AcceptanceManifest,beforeProgramBatch7AcceptanceTimings,beforeProgramBatch7AcceptanceSource} from "./question-program-batch7-acceptance-test-support";
import {createHash} from "node:crypto";
import {readFileSync} from "node:fs";
import {describe, expect, it} from "vitest";
import {SYNTHETIC_CLINICAL_RELEASE as actualLive, QUESTION_CATALOG_RELEASE as catalog} from "./synthetic-content";
import {QUESTION_SHIP_MANIFEST as actualManifest} from "./question-ship-manifest";
import {ANSWER_CHOICE_TIMING_REGISTRY as actualTimings} from "./answer-choice-timing";
import {
  QUESTION_FLAG_D97AA716_CASES as cases, QUESTION_FLAG_D97AA716_QUESTIONS as questions,
  QUESTION_FLAG_D97AA716_RETAINED_INPUT as retained, QUESTION_FLAG_D97AA716_CLAIMS as claims,
  QUESTION_FLAG_D97AA716_SOURCES as sources, QUESTION_FLAG_D97AA716_TIMING_ENTRIES as estimates,
  QUESTION_FLAG_D97AA716_CANDIDATE_TEST_ORDER_RECORDS as orders, applyQuestionFlagD97aa716Revisions as apply,
} from "./question-flag-d97aa716-20261112";

const live=beforeProgramBatch7AcceptanceRelease(actualLive);
const manifest=beforeProgramBatch7AcceptanceManifest(actualManifest);
const timings=beforeProgramBatch7AcceptanceTimings(actualTimings);
const read = (path: string) => JSON.parse(readFileSync(new URL("../../../" + path, import.meta.url), "utf8"));
const input = read("tools/question-quality/fixtures/question-flag-d97aa716-before-20261112.json");
const round1 = read("tools/question-quality/fixtures/question-flag-d97aa716-round2-intake-20261112.json");
const packet = round1.round1Packet;
const lint = round1.round1Lint;
const digest = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");
const letters = /\b(?:region|path|target)\s+[ABC]\b|\bB is an attractive|enhancement at B|\bof [AB] through/i;

describe("owner flag d97aa716 concrete biopsy routes", () => {
  it("records three genuinely fresh letter-labelled nodes and the two retired legacy siblings", () => {
    expect(input.selected).toHaveLength(3);
    expect(input.siblingAudit).toHaveLength(5);
    for (const row of input.selected) {
      expect(live.cases.find(cs => cs.id === row.case.id)).toEqual(row.case);
      expect(row.reachability).toMatchObject({issue: null, receipt: {status: "applied"}});
      expect(row.reachability.admittedVariantIds).toContain(row.question.id);
    }
    expect(input.siblingAudit.filter((row: {fresh: boolean}) => !row.fresh)
      .map((row: {questionVariantId: string}) => row.questionVariantId).sort()).toEqual([
      "question.soft-tissue-mass.specialist-planned-biopsy.v3",
      "question.soft-tissue-mass.specialist-planned-biopsy.v4",
    ]);
  });

  it("keeps stable concepts, choice identities, keys and all earlier decision nodes", () => {
    expect(cases).toHaveLength(3);
    for (const [index, cs] of cases.entries()) {
      const before = retained.cases[index]!;
      const row = input.selected[index];
      const old = before.decisionNodes.find(node => node.id === row.nodeId)!;
      const node = cs.decisionNodes.find(node => node.id === row.nodeId)!;
      expect(node.questionVariantId).not.toBe(old.questionVariantId);
      expect(node.primaryConceptId).toBe("concept.soft-tissue-mass.specialist-planned-biopsy");
      expect(node.answerChoices.map(choice => [choice.id, choice.isCorrect, choice.serviceRequest]))
        .toEqual(old.answerChoices.map(choice => [choice.id, choice.isCorrect, choice.serviceRequest]));
      for (const previous of before.decisionNodes.filter(node => node.id !== row.nodeId))
        expect(cs.decisionNodes.find(node => node.id === previous.id)).toEqual(previous);
      const {decisionNodes: _a, learningSummary: _b, ...oldHeader} = before;
      const {decisionNodes: _c, learningSummary: _d, ...newHeader} = cs;
      expect(newHeader).toEqual(oldHeader);
      expect(node.shuffleAnswers).toBe(true);
    }
  });

  it("uses named muscle routes throughout every revised visible field and feedback", () => {
    for (const [index, cs] of cases.entries()) {
      const node = cs.decisionNodes.find(node => node.questionVariantId === questions[index]!.id)!;
      expect(JSON.stringify({stem: node.stem, update: node.currentUpdate, exhibit: node.exhibit,
        choices: node.answerChoices, explanation: node.explanation, teaching: node.teachingPoint,
        dispositions: node.terminalDispositions})).not.toMatch(letters);
      expect(node.exhibit?.kind).toBe("table");
      expect(node.answerChoices).toHaveLength(4);
      expect(node.answerChoices.every(choice => /biopsy with (?:a|an) (?:anterior|posterior|medial|lateral) approach through/.test(choice.label))).toBe(true);
      expect(packet[index].selfCheck.counterfactual).toBeTruthy();
      expect(packet[index].clinicalReviewBoundary).toContain("Melissa Rowland");
    }
  });

  it("reuses the original eleven atomic claims and twelve sources without a new medical claim", () => {
    expect(claims).toEqual(input.claims);
    expect(sources).toEqual(input.sources);
    expect(claims).toHaveLength(11);
    expect(sources).toHaveLength(12);
    for (const [index, question] of questions.entries()) {
      expect(question.supportingEvidenceClaimIds).toEqual(input.selected[index].question.supportingEvidenceClaimIds);
      expect(question.reviewStatus).toBe("needs_clinician_review");
      expect(question.lastClinicianReview).toBeNull();
      for (const id of question.supportingEvidenceClaimIds) expect(claims.some(claim => claim.id === id)).toBe(true);
    }
  });

  it("provides all twelve exact biopsy estimates and future-planned dispositions", () => {
    expect(estimates).toHaveLength(3);
    expect(orders).toHaveLength(12);
    for (const row of orders) {
      const cs = cases.find(cs => cs.id === row.caseId)!;
      const node = cs.decisionNodes.find(node => node.id === row.nodeId)!;
      expect(node.questionVariantId).toBe(row.questionVariantId);
      expect(node.answerChoices.find(choice => choice.id === row.choiceId)!.label).toBe(row.choiceLabel);
      expect(row.timingProfileId).toBe("timing.test.biopsy");
      expect(row.disposition).toEqual({kind: "not_executed", reason: "future_planned"});
    }
  });

  it("has zero raw findings for all three revised variants and all twelve patient contexts", () => {
    expect(lint).toMatchObject({targetVariants: 3, targetProfileContexts: 12, targetFindings: 0, suppressedFindings: 0});
    expect(lint.inheritedFindings.reduce((n: number, row: {findings: unknown[]}) => n + row.findings.length, 0)).toBe(4);
    for (const [index, cs] of cases.entries()) {
      const node = cs.decisionNodes.find(node => node.questionVariantId === questions[index]!.id)!;
      expect(digest(node)).toBe(packet[index].frozenPreservation.afterNodeSha256);
    }
  });

  it("keeps the original live projection, authority, timing archive and protected inputs exact", () => {
    expect(digest(live)).toBe(input.live.sha256);
    expect(digest(manifest)).toBe(input.manifestSha256);
    expect(digest(catalog)).toBe(input.catalogSha256);
    expect(digest(timings)).toBe(input.timingSha256);
    for (const row of input.protectedInputs)
      expect(createHash("sha256").update(beforeProgramBatch7AcceptanceSource(row.path,readFileSync(new URL("../../../" + row.path, import.meta.url),"utf8"))).digest("hex"), row.path).toBe(row.sha256);
    const preview = apply(live.cases);
    for (const cs of live.cases.filter(cs => !cases.some(candidate => candidate.id === cs.id)))
      expect(preview.find(candidate => candidate.id === cs.id)).toBe(cs);
  });

  it.each(["earlier node", "target update", "target option"])("rejects altered retained %s source", field => {
    const changed = structuredClone(retained.cases);
    if (field === "earlier node") changed[0]!.decisionNodes[0]!.stem += " changed";
    if (field === "target update") changed[0]!.decisionNodes[1]!.currentUpdate += " changed";
    if (field === "target option") changed[0]!.decisionNodes[1]!.answerChoices[0]!.label += " changed";
    expect(() => apply(changed)).toThrow(/retained input changed/);
  });
});

import {beforeProgramBatch7AcceptanceRelease,beforeProgramBatch7AcceptanceManifest,beforeProgramBatch7AcceptanceTimings,beforeProgramBatch7AcceptanceSource} from "./question-program-batch7-acceptance-test-support";
import {createHash} from "node:crypto";
import {readFileSync} from "node:fs";
import {describe, expect, it} from "vitest";
import {SYNTHETIC_CLINICAL_RELEASE as actualLive, QUESTION_CATALOG_RELEASE as catalog} from "./synthetic-content";
import {QUESTION_SHIP_MANIFEST as actualManifest} from "./question-ship-manifest";
import {ANSWER_CHOICE_TIMING_REGISTRY as actualTimings} from "./answer-choice-timing";
import {QUESTION_FLAG_D97AA716_CASES as round1Cases} from "./question-flag-d97aa716-20261112";
import {
  QUESTION_FLAG_D97AA716_ROUND2_CASES as cases, QUESTION_FLAG_D97AA716_ROUND2_QUESTIONS as questions,
  QUESTION_FLAG_D97AA716_ROUND2_RETAINED_INPUT as retained, QUESTION_FLAG_D97AA716_CLAIMS as claims,
  QUESTION_FLAG_D97AA716_SOURCES as sources, QUESTION_FLAG_D97AA716_ROUND2_TIMING_ENTRIES as estimates,
  QUESTION_FLAG_D97AA716_ROUND2_CANDIDATE_TEST_ORDER_RECORDS as orders,
  applyQuestionFlagD97aa716Round2Revisions as apply,
} from "./question-flag-d97aa716-round2-20261112";

const live=beforeProgramBatch7AcceptanceRelease(actualLive);
const manifest=beforeProgramBatch7AcceptanceManifest(actualManifest);
const timings=beforeProgramBatch7AcceptanceTimings(actualTimings);
const bytes = (path: string) => Buffer.from(beforeProgramBatch7AcceptanceSource(path,readFileSync(new URL("../../../" + path, import.meta.url),"utf8")));
const read = (path: string) => JSON.parse(bytes(path).toString("utf8"));
const input = read("tools/question-quality/fixtures/question-flag-d97aa716-before-20261112.json");
const intake = read("tools/question-quality/fixtures/question-flag-d97aa716-round2-intake-20261112.json");
const packet = read("docs/research/question-flag-d97aa716-20261112.json");
const lint = read("tools/question-quality/question-flag-d97aa716-lint-20261112.json");
const review = read("docs/research/question-flag-d97aa716-review-20261112.json");
const bytesDigest = (value: string | Buffer) => createHash("sha256").update(value).digest("hex");
const digest = (value: unknown) => bytesDigest(JSON.stringify(value));
const letters = /\b(?:region|path|target)\s+[ABC]\b|\bB is an attractive|enhancement at B|\bof [AB] through/i;

describe("owner flag d97aa716 round2 review closure", () => {
  it("retains exact reviewed round1 modules and archives all prior review projections", () => {
    for (const row of intake.files.filter((row: {path: string}) => /(?:question-flag-d97aa716-20261112(?:-data)?\.ts|(?:author|review)-question-flag-d97aa716-20261112\.mjs|questionFlagD97aa716SaveCompatibility\.test\.ts|question-flag-d97aa716-review-20261112\.json)$/.test(row.path)))
      expect(bytesDigest(bytes(row.path)), row.path).toBe(row.sha256);
    for (const [path, value] of [
      ["docs/research/question-flag-d97aa716-20261112.json", intake.round1Packet],
      ["docs/research/sources-question-flag-d97aa716-20261112.json", intake.round1Ledger],
      ["tools/question-quality/question-flag-d97aa716-lint-20261112.json", intake.round1Lint],
    ] as const) expect(bytesDigest(JSON.stringify(value, null, 2) + "\n"))
      .toBe(intake.files.find((row: {path: string}) => row.path === path).sha256);
    const testPath = "packages/clinical-content/src/question-flag-d97aa716-20261112.test.ts";
    const restored = bytes(testPath).toString("utf8").replace(
      'const round1 = read("tools/question-quality/fixtures/question-flag-d97aa716-round2-intake-20261112.json");\nconst packet = round1.round1Packet;\nconst lint = round1.round1Lint;',
      'const packet = read("docs/research/question-flag-d97aa716-20261112.json");\nconst lint = read("tools/question-quality/question-flag-d97aa716-lint-20261112.json");');
    expect(bytesDigest(restored)).toBe(intake.files.find((row: {path: string}) => row.path === testPath).sha256);
  });

  it("preserves concepts, all answer identities and keys, patient headers and every preceding MRI node", () => {
    expect(cases).toHaveLength(3);
    expect(questions.map(question => question.id)).toEqual([
      "question.soft-tissue-mass.specialist-planned-biopsy.v1.r6",
      "question.soft-tissue-mass.specialist-planned-biopsy.v2.r6",
      "question.topic-soft-tissue-sarcoma-desmoid.calf-core-tract.20261111.v3",
    ]);
    for (const [index, cs] of cases.entries()) {
      const before = retained.cases[index]!;
      const row = input.selected[index];
      const old = before.decisionNodes.find(node => node.id === row.nodeId)!;
      const node = cs.decisionNodes.find(node => node.id === row.nodeId)!;
      expect(node.primaryConceptId).toBe("concept.soft-tissue-mass.specialist-planned-biopsy");
      expect(node.answerChoices.map(choice => [choice.id, choice.isCorrect, choice.serviceRequest]))
        .toEqual(old.answerChoices.map(choice => [choice.id, choice.isCorrect, choice.serviceRequest]));
      for (const previous of before.decisionNodes.filter(node => node.id !== row.nodeId))
        expect(cs.decisionNodes.find(node => node.id === previous.id)).toEqual(previous);
      const {decisionNodes: _a, learningSummary: _b, ...oldHeader} = before;
      const {decisionNodes: _c, learningSummary: _d, ...newHeader} = cs;
      expect(newHeader).toEqual(oldHeader);
      expect(node.shuffleAnswers).toBe(true);
    }
  });

  it("supplies percutaneous access and a constructed resection field without claiming clinician confirmation", () => {
    for (const [index, cs] of cases.entries()) {
      const node = cs.decisionNodes.find(node => node.questionVariantId === questions[index]!.id)!;
      expect(node.currentUpdate).toContain("Both enhancing solid targets can be sampled percutaneously");
      expect(node.currentUpdate).toContain("skin entry");
      expect(node.currentUpdate).toContain("outside the proposed specimen");
      expect(node.explanation).toContain("must be removable with the definitive specimen");
      expect(packet[index].clinicalReviewBoundary).toContain("No clinician confirmation has occurred");
      expect(packet[index].clinicalReviewBoundary).toContain("Melissa Rowland");
    }
  });

  it("keeps concrete anatomy, precise adductor-longus wording and a complete balanced option matrix", () => {
    for (const [index, cs] of cases.entries()) {
      const node = cs.decisionNodes.find(node => node.questionVariantId === questions[index]!.id)!;
      expect(JSON.stringify({stem: node.stem, update: node.currentUpdate, exhibit: node.exhibit,
        choices: node.answerChoices, explanation: node.explanation, teaching: node.teachingPoint,
        dispositions: node.terminalDispositions})).not.toMatch(letters);
      expect(node.answerChoices).toHaveLength(4);
      const parts = node.answerChoices.map(choice => choice.label.split(" with "));
      expect(new Set(parts.map(row => row[0])).size).toBe(2);
      expect(new Set(parts.map(row => row[1])).size).toBe(2);
      expect(new Set(parts.map(row => row.join(" with "))).size).toBe(4);
    }
    expect(JSON.stringify(questions[0])).not.toContain("adductor muscle");
    expect(questions[0]!.answerChoices.filter(choice => choice.label.includes("adductor longus"))).toHaveLength(2);
  });

  it("withholds the unverified calf compartment assertion instead of inventing anatomical support", () => {
    const calf = cases[2]!.decisionNodes[0]!;
    expect(JSON.stringify({update: calf.currentUpdate, exhibit: calf.exhibit, choices: calf.answerChoices,
      explanation: calf.explanation, teaching: calf.teachingPoint, dispositions: calf.terminalDispositions})).not.toMatch(/compartment/i);
    expect(questions[2]!.supportingEvidenceClaimIds).not.toContain("claim.qq20261102b.sarcoma-method-and-tract");
    expect(packet[2].withheldAssertion).toContain("does not verify");
    expect(packet[2].selfCheck.sourceClosure).toContain("No unverified calf");
    expect(packet[2].keyChanged).toBe(false);
  });

  it("reuses eleven unchanged claims and twelve records with explicit tract and viable-target mappings", () => {
    expect(claims).toEqual(input.claims);
    expect(sources).toEqual(input.sources);
    expect(claims).toHaveLength(11);
    expect(sources).toHaveLength(12);
    for (const [index, question] of questions.entries()) {
      expect(question.supportingEvidenceClaimIds).toContain("claim.question-topic-soft-tissue-sarcoma-desmoid.tract-excision");
      expect(question.supportingEvidenceClaimIds).toContain("claim.qq20261102a.sarcoma-viable-biopsy-target");
      expect(question.reviewStatus).toBe("needs_clinician_review");
      expect(question.lastClinicianReview).toBeNull();
      for (const id of question.supportingEvidenceClaimIds) expect(claims.some(claim => claim.id === id)).toBe(true);
      expect(packet[index].evidenceMapping.find((row: {fields: string[]}) => row.fields.includes("Explanation: tract excision")).claimIds)
        .toEqual(["claim.question-topic-soft-tissue-sarcoma-desmoid.tract-excision"]);
    }
  });

  it("responds to all 36 review notes and projects chief complaints plus exact round1 before content", () => {
    let count = 0;
    for (const [index, row] of packet.entries()) {
      expect(row.round).toBe(2);
      expect(row.sourceView).toBe("flag-d97aa716-round2");
      expect(row.reviewResponse.reviewSha256).toBe(bytesDigest(bytes("docs/research/question-flag-d97aa716-review-20261112.json")));
      for (const type of ["fairness", "suggestion"]) {
        const notes = row.reviewResponse.notes.filter((note: {type: string}) => note.type === type);
        expect(notes.map((note: {noteIndex: number}) => note.noteIndex)).toEqual(
          (type === "fairness" ? review[index].fairness : review[index].suggestions).map((_: unknown, n: number) => n + 1));
        expect(notes.every((note: {response: string}) => note.response.length > 20)).toBe(true);
        count += notes.length;
      }
      const oldCase = round1Cases[index]!;
      const old = oldCase.decisionNodes.find(node => node.id === row.nodeId)!;
      expect(row.before.variantId).toBe(old.questionVariantId);
      expect(row.before["Current update"]).toBe(old.currentUpdate);
      expect(row.before["Chief complaint"]).toBe(oldCase.chiefComplaint);
      expect(row.after["Chief complaint"]).toBe(cases[index]!.chiefComplaint);
      expect(row.after.Task).toContain(["thigh mass", "upper-arm mass", "calf mass"][index]);
      expect(row.keyOrderNotice).toContain("Key shown first for review only");
      expect(row.selfCheck.counterfactual).toBeTruthy();
    }
    expect(count).toBe(36);
  });

  it("provides all twelve exact biopsy estimates and future-planned dispositions", () => {
    expect(estimates).toHaveLength(3);
    expect(orders).toHaveLength(12);
    for (const row of orders) {
      const cs = cases.find(cs => cs.id === row.caseId)!;
      const node = cs.decisionNodes.find(node => node.id === row.nodeId)!;
      expect(node.questionVariantId).toBe(row.questionVariantId);
      expect(node.answerChoices.find(choice => choice.id === row.choiceId)!.label).toBe(row.choiceLabel);
      expect(row.timingProfileId).toBe("timing.test.biopsy");
      expect(row.disposition).toEqual({kind: "not_executed", reason: "future_planned"});
    }
  });

  it("has zero raw cue findings across all twelve patient contexts without suppressions", () => {
    expect(lint).toMatchObject({round: 2, targetVariants: 3, targetProfileContexts: 12, targetFindings: 0, suppressedFindings: 0});
    expect(lint.inheritedFindings.reduce((n: number, row: {findings: unknown[]}) => n + row.findings.length, 0)).toBe(4);
    for (const [index, cs] of cases.entries()) {
      const node = cs.decisionNodes.find(node => node.questionVariantId === questions[index]!.id)!;
      expect(digest(node)).toBe(packet[index].frozenPreservation.afterNodeSha256);
    }
  });

  it("leaves every live/default/manifest/catalog/timing and protected source input exact", () => {
    expect(digest(live)).toBe(input.live.sha256);
    expect(digest(manifest)).toBe(input.manifestSha256);
    expect(digest(catalog)).toBe(input.catalogSha256);
    expect(digest(timings)).toBe(input.timingSha256);
    for (const row of input.protectedInputs) expect(bytesDigest(bytes(row.path)), row.path).toBe(row.sha256);
    const preview = apply(live.cases);
    for (const cs of live.cases.filter(cs => !cases.some(candidate => candidate.id === cs.id)))
      expect(preview.find(candidate => candidate.id === cs.id)).toBe(cs);
  });

  it.each(["earlier node", "target update", "target option"])("rejects altered retained %s source", field => {
    const changed = structuredClone(retained.cases);
    if (field === "earlier node") changed[0]!.decisionNodes[0]!.stem += " changed";
    if (field === "target update") changed[0]!.decisionNodes[1]!.currentUpdate += " changed";
    if (field === "target option") changed[0]!.decisionNodes[1]!.answerChoices[0]!.label += " changed";
    expect(() => apply(changed)).toThrow(/retained input changed/);
  });
});

import {beforeProgramBatch7AcceptanceRelease} from "../../../packages/clinical-content/src/question-program-batch7-acceptance-test-support";
import {describe, expect, it} from "vitest";
import {
  PROTOTYPE_DOMAIN_CONTEXT as liveContext, gameReducer, getCurrentQuestion,
  applyFsrsReview, createNewFsrsCard, type GameState, type GameCommand, type DomainContext,
} from "@gamify-surgery/game-domain";
import {
  QUESTION_FLAG_D97AA716_RETAINED_INPUT as retained,
  applyQuestionFlagD97aa716Revisions as apply,
} from "../../../packages/clinical-content/src/question-flag-d97aa716-20261112";
import {createLevelFourRoomsQaState} from "../../../tests/fixtures/level-four-rooms";
import {snapshotCopy} from "./session/cloud/snapshotCodec";
import {loadCloudEvidenceCheckpoint} from "./session/cloud/codecEvidence";
import {codecTestCampaign} from "./session/cloud/codecTestSupport";

const current:DomainContext={...liveContext,clinicalRelease:beforeProgramBatch7AcceptanceRelease(liveContext.clinicalRelease)};
const preview: DomainContext = {...current, clinicalRelease: {...current.clinicalRelease,
  cases: apply(current.clinicalRelease.cases)}};
const encounterId = "encounter.flag.d97aa716.frozen";
const reviewedAtMs = 1_800_000_000_000;

function execute(state: GameState, command: GameCommand, context: DomainContext) {
  const next = gameReducer(state, command, context);
  expect(next.operationReceipts[command.operationId], command.operationId).toMatchObject({status: "applied"});
  return next;
}

function ready(state: GameState, nodeIndex: number): GameState {
  const pending = state.encounters[encounterId]!.pendingResult;
  if (pending && pending.dueTick > state.facilityTick) {
    const remaining = pending.dueTick - state.facilityTick;
    for (let tick = 0; tick < remaining; tick++) state = execute(state,
      {type: "ADVANCE_TICK", operationId: `flag.d97aa716.service.${nodeIndex}.${tick}`, advancedAtRealMs: reviewedAtMs}, preview);
  }
  for (let tick = 0; tick < 240 && !getCurrentQuestion(state, encounterId, preview); tick++) {
    state = execute(state, {type: "ADVANCE_TICK", operationId: `flag.d97aa716.ready.${nodeIndex}.${tick}`,
      advancedAtRealMs: reviewedAtMs}, preview);
    const encounter = state.encounters[encounterId]!;
    if (state.openChartEncounterId !== encounterId && encounter.checkInStatus === "checked_in" && !encounter.patientMovement)
      state = execute(state, {type: "OPEN_CHART", operationId: `flag.d97aa716.open.${nodeIndex}.${tick}`, encounterId}, preview);
  }
  expect(getCurrentQuestion(state, encounterId, preview), "Frozen question reaches the existing 240-tick physical-readiness bound").not.toBeNull();
  return state;
}

describe("flag d97aa716 exact frozen questions and stable FSRS", () => {
  it.each(retained.cases)("reopens and completes $id format-3 with its original labels and identities", async clinicalCase => {
    let state = createLevelFourRoomsQaState(current);
    state = execute(state, {type: "PLACE_ROOM", operationId: "flag.d97aa716.exam",
      roomDefinitionId: "room.examination", roomId: "room.flag.d97aa716.exam", x: 35, y: 24, orientation: 0}, current);
    state = execute(state, {type: "PLACE_DOOR", operationId: "flag.d97aa716.door",
      roomId: "room.flag.d97aa716.exam", doorId: "door.flag.d97aa716.exam", side: "south", offset: 1}, current);
    Object.assign(state, {paused: false, serviceAppointmentsEnabled: false,
      nextRoutineArrivalTick: Number.MAX_SAFE_INTEGER, nextEmployeeDiscussionTick: Number.MAX_SAFE_INTEGER,
      nextFinancialPostingTick: Number.MAX_SAFE_INTEGER});
    const conceptId = "concept.soft-tissue-mass.specialist-planned-biopsy";
    const previous = applyFsrsReview(createNewFsrsCard(0), "Good", 1000, current.balanceRelease.learning);
    state.learningHistories[conceptId] = {conceptId, card: previous.card, reviews: [{
      id: "review.flag.d97aa716.prior", encounterId: "encounter.flag.d97aa716.prior",
      decisionNodeId: clinicalCase.decisionNodes.at(-1)!.id,
      questionVariantId: clinicalCase.decisionNodes.at(-1)!.questionVariantId,
      patientPresentationVariantId: clinicalCase.patientPresentationVariantId, primaryConceptId: conceptId,
      answerChoiceId: clinicalCase.decisionNodes.at(-1)!.answerChoices.find(choice => choice.isCorrect)!.id,
      correct: true, rating: "Good", reviewedAtMs: 1000, facilityTick: 0, schedulerLog: previous.log,
    }]};
